'use strict';
const atlasLegacyPaint=paintTerrain,atlasLegacyDraw=drawTerrain;
function atlasRiverPath(points){ctx.beginPath();for(let i=0;i<points.length;i++){let [x,y]=points[i];i?ctx.lineTo(x,y):ctx.moveTo(x,y);}}
function atlasWater(){ctx.save();ctx.lineJoin='round';ctx.lineCap='round';for(let p of [mapSpec.main,...mapSpec.branches]){atlasRiverPath(p);for(let [w,c] of [[33,'#c3d4b4'],[25,'#e2d9b4'],[18,'#619ca5'],[15,'#85bfc0'],[7,'#abd8cd']]){ctx.strokeStyle=c;ctx.lineWidth=w;ctx.stroke();}}ctx.restore();}
paintTerrain=function(){if(!activeAtlasMap)return atlasLegacyPaint();let b=mapSpec.bounds;ctx.save();ctx.fillStyle='#e6edda';ctx.fillRect(b.xmin,b.ymin,b.xmax-b.xmin,b.ymax-b.ymin);
 for(let e of hills){contourPath(e);ctx.fillStyle='#bacda6';ctx.fill();ctx.save();ctx.clip();for(let k=0;k<5;k++){contourPath(e,1-k*.17,-k*3,-k*8);ctx.fillStyle=['#c4d4ac','#cedcb8','#d8e2c2','#e1e8cf','#e9edd8'][k];ctx.fill();}ctx.restore();}
 // Deterministic groves: no simulation RNG and no new construction obstacles.
 for(let y=b.ymin+80;y<b.ymax-50;y+=63)for(let x=b.xmin+70;x<b.xmax-50;x+=77){let wave=Math.sin(x*.014+y*.021)+Math.cos(y*.017-x*.009);if(wave<1.18||riverDistance({x,y})<43||mountainDistance({x,y})<25||hills.some(e=>inEllipse({x,y},e)))continue;for(let i=0;i<4;i++)artTree(x+i*9-14,y+Math.sin(i*7)*9,.8+(i%2)*.15,mapSpec.id==='west');}
 // Mountain facets use the same exact footprints as construction tests.
 const layer=document.createElement('canvas');layer.width=2640;layer.height=1800;let live=ctx;try{ctx=layer.getContext('2d');ctx.scale(1.2,1.2);ctx.translate(1000,300);
 for(let [id,e] of mountains.entries()){contourPath(e);ctx.fillStyle='#9caf99';ctx.fill();ctx.save();ctx.clip();let ridge=[[-1.1,.12],[-.7,-.22],[-.35,-.7],[.02,-.3],[.35,-.65],[.7,-.15],[1.12,.12]].map(([x,y])=>({x:e.x+x*e.rx,y:e.y+y*e.ry}));for(let i=0;i<ridge.length-1;i++){let a=ridge[i],z=ridge[i+1],n={x:(a.x+z.x)/2-15,y:e.y-e.ry*1.3},s={x:(a.x+z.x)/2+e.rx*.12*Math.sin(i+id),y:e.y+e.ry};terrainPolygon([a,z,n],['#c7cfb9','#d6dac2','#bbc8b1'][i%3]);terrainPolygon([a,z,s],['#8fa78f','#789685','#a2b39a'][i%3]);}for(let i of [2,4]){let a=ridge[i];terrainPolygon([{x:a.x-12,y:a.y+18},a,{x:a.x+14,y:a.y+16},{x:a.x+3,y:a.y+12}],'#edf0df');}ctx.restore();}
 ctx.globalCompositeOperation='destination-out';ctx.lineWidth=64;ctx.lineJoin='round';ctx.lineCap='round';for(let p of [mapSpec.main,...mapSpec.branches]){atlasRiverPath(p);ctx.stroke();}
 }finally{ctx=live;}ctx.drawImage(layer,-1000,-300,2200,1500);layer.width=1;layer.height=1;
 atlasWater();ctx.strokeStyle='#a4b49a';ctx.lineWidth=2;ctx.setLineDash([5,12]);ctx.strokeRect(b.xmin+2,b.ymin+2,2196,1496);ctx.setLineDash([]);
 let labels=mapSpec.id==='east'?[['北 原',300,-190],['东 部 平 原',810,730],['南 川',-400,880]]:[['云 岭',100,-130],['西 原',-650,450],['南 部 盆 地',230,1080]];for(let [t,x,y] of labels)text(t,x,y,14,'#82967b');ctx.restore();};
drawTerrain=function(){if(!activeAtlasMap)return atlasLegacyDraw();let left=-view.x/view.scale,top=-view.y/view.scale;ctx.fillStyle='#d9e2d2';ctx.fillRect(left-30,top-30,W/view.scale+60,H/view.scale+60);if(!terrainCache){let cache=document.createElement('canvas');cache.width=2640;cache.height=1800;let live=ctx;try{ctx=cache.getContext('2d');ctx.scale(1.2,1.2);ctx.translate(1000,300);paintTerrain();terrainCache=cache;}finally{ctx=live;}}ctx.drawImage(terrainCache,-1000,-300,2200,1500);};
